<?php require 'config.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$db->prepare('SELECT e.*,(SELECT COUNT(*) FROM registrations WHERE event_id=e.id) booked FROM events e WHERE e.id=? AND active=1');$s->execute([$id?:0]);$e=$s->fetch();if(!$e){http_response_code(404);exit('Event not found');}head('Event details');?><section class="card"><h1><?=h($e['title'])?></h1><p><?=nl2br(h($e['description']))?></p><p>Venue: <?=h($e['venue'])?></p><p>Date: <?=h($e['event_date'])?></p><p>Seats: <?=h($e['booked'])?> / <?=h($e['capacity'])?></p><?php if(strtotime($e['event_date'])<=time()):?><p>Registration closed.</p><?php elseif($e['booked']>=$e['capacity']):?><p>Event full.</p><?php elseif(empty($_SESSION['uid'])):?><a class="btn" href="login.php">Login to register</a><?php else:?><form method="post" action="registration.php"><input type="hidden" name="token" value="<?=h(token())?>"><input type="hidden" name="event_id" value="<?=h($id)?>"><button>Register for event</button></form><?php endif;?></section><?php foot();?>